// Synthetic public aggregates only. Independent canonical/hash oracle, no operational records.
import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';import{createHash,webcrypto}from'node:crypto';
export const clone=structuredClone,plain=x=>JSON.parse(JSON.stringify(x));
export const DAYS=['SUNDAY','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'],MEALS=['breakfast','lunch','dinner'];
export const G='11111111-1111-4111-8111-111111111111',OP='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',E='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',COMMIT='c'.repeat(40),PRIVATE='d'.repeat(40),NOW=Date.parse('2026-11-17T12:00:00Z');
export const canonical=v=>v===null||typeof v!=='object'?JSON.stringify(v):Array.isArray(v)?'['+v.map(canonical).join(',')+']':'{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}';
export const digest=v=>'sha256:'+createHash('sha256').update(canonical(v),'utf8').digest('hex'),wire=v=>new TextEncoder().encode(canonical(v)+'\n'),seal=bytes=>'sha256:'+createHash('sha256').update(bytes).digest('hex');
export const html=fs.readFileSync(process.env.SERVING_PROTOCOL_HTML||new URL('../../index.html',import.meta.url),'utf8');
export function api(crypto=webcrypto,includePrivate=true){let src='';const regions=[['HOUSE','flow-validity'],...(includePrivate?[['DOOR','private-generation-v1']]:[]),['HOUSE','serving-protocol-v1']];for(const[owner,region]of regions){const begin=`/* ${owner}_TESTABLE_CORE_START ${region} */`,end=`/* ${owner}_TESTABLE_CORE_END ${region} */`,a=html.indexOf(begin),z=html.indexOf(end,a+begin.length);assert.ok(a>=0&&z>a,'actual marked '+region+' core exists');src+=html.slice(a+begin.length,z)+'\n'}const forbidden=[];const noIO=()=>{forbidden.push(true);throw Error('Inactive serving core attempted ambient capability')};const c=vm.createContext({crypto,TextEncoder,TextDecoder,Uint8Array,URL,console:{log:noIO,warn:noIO,error:noIO},fetch:noIO,localStorage:{getItem:noIO,setItem:noIO,removeItem:noIO},setTimeout:noIO});vm.runInContext(src,c);for(const n of['houseServingV1Prepare','doorServingV1Build','houseServingV1Validate','houseServingV1CreateState','houseServingV1Begin','houseServingV1Promote','houseServingV1Resolve'])assert.equal(typeof c[n],'function',n);return{c,forbidden}}
export const CATALOGUE=digest({schema:1,main:COMMIT,sharedLibrary:'f'.repeat(40),doorRecipeDataSha256:'1'.repeat(64),libraryPublicSha256:'2'.repeat(64)});
export function material(){return{schema:1,protocol:'door-serving-v1',site:'rexdale',releaseBinding:{generationId:G,operationId:OP},calendar:{mode:'standard',cycleStart:'2026-06-07',cycleWeeks:4,weekStartsOn:'SUNDAY',zone:'America/Toronto'},registry:{summary:{total:2,active:2,anaphylactic:0},headcounts:{regular:2,halal:0,vegan:0,diabetic:0,glutenFree:0,noDairy:0,soft:0}},rotation:[1,2,3,4].flatMap(w=>DAYS.flatMap(d=>MEALS.map(m=>({key:w+'|'+d+'|'+m,menu:{regular:'Fixture rice',vegan:'Fixture rice',halal:'Fixture rice'},components:[{recipeId:'fixture-rice',name:'Fixture rice',role:'main'}],unresolvedComponents:[],coverage:{ordinary:'complete'},demand:{unit:'recipients',allocations:'known',standardPortions:'eligible',reason:'verified-standard'},sectionCounts:{Regular:2},resolution:{schema:1,state:'complete',expectedResidents:2,ordinaryResolved:2,ordinaryUnresolved:0,separateResidents:0,separateDefinitionState:'not-required',quantitiesComplete:true,definitionRevision:'definition-v1',catalogueRevision:'codex:'+CATALOGUE},componentAllocations:{'fixture-rice':2}})))),dated:[],datedDecisions:[],recipes:[{recipeId:'fixture-rice',canonicalName:'Fixture rice',sourceFingerprint:{kind:'codex-content',value:'e'.repeat(64)},catalogueRevision:{kind:'codex-public-snapshot',value:CATALOGUE},allergenState:'known',allergenFlags:{hasCorn:true},portionBasis:{servings:10,unit:'standard-serving'}}]}}
const pick=(s,keys)=>Object.fromEntries(keys.filter(k=>Object.hasOwn(s,k)).map(k=>[k,clone(s[k])]));
export function oracle(m){const base={schema:1,protocol:m.protocol,site:m.site,releaseBinding:clone(m.releaseBinding)},inputs={site:m.site,menu:{...base,rotation:m.rotation.map(s=>pick(s,['key','menu','components','unresolvedComponents'])),dated:m.dated.map(s=>pick(s,['key','kind','week','day','menu','components','unresolvedComponents']))},dated:{...base,decisions:clone(m.datedDecisions)},registry:{...base,registry:clone(m.registry),rotation:m.rotation.map(s=>pick(s,['key','sectionCounts','resolution','coverage','demand','componentAllocations'])),dated:m.dated.map(s=>pick(s,['key','sectionCounts','resolution','coverage','demand','componentAllocations']))},recipe:{...base,records:clone(m.recipes)},calendar:clone(m.calendar)},components=Object.fromEntries(['menu','dated','registry','recipe','calendar'].map(k=>[k,digest(inputs[k])])),flowBase={schema:1,inputRevision:digest({schema:1,site:m.site,components}),components,calendar:clone(m.calendar)};return{material:clone(m),publicProjectionBasisDigest:digest(m),publicInputWitness:flowBase.inputRevision,flowBase}}
export const ref=w=>({schema:1,generationId:G,privateCommit:PRIVATE,operationId:OP,publicInputWitness:w}),publication=(sequence=1)=>({epoch:E,sequence}),path=(sequence=1)=>`protocol-v1/releases/${E}/${sequence}/frame.json`;
export async function built(c,m=material(),sequence=1){const p=await c.houseServingV1Prepare(m);assert.equal(p.ok,true);const b=await c.doorServingV1Build(p.prepared,ref(p.prepared.publicInputWitness),publication(sequence));assert.equal(b.ok,true);return b}
export async function valid(c,b){return c.houseServingV1Validate(b.pointer,b.frameBytes,{site:'rexdale',expectedPath:path(b.pointer.flow.publication.sequence)})}
export function manual(s){s.components=[];s.unresolvedComponents=[{name:'Fixture manual dish',role:'main',reason:'manual-unlinked'}];s.menu.regular='Fixture manual dish';s.resolution.state='incomplete';s.resolution.quantitiesComplete=false;s.resolution.ordinaryResolved=0;s.resolution.ordinaryUnresolved=2;s.coverage.ordinary='incomplete';s.demand={unit:'recipients',allocations:'unavailable',standardPortions:'unavailable',reason:'unresolved-component'};delete s.componentAllocations;return s}
